//
// California personal income tax withholding: EDD Method B (Exact
// Calculation Method), computed on the annual payroll period and divided
// back to the pay period, which EDD's own Examples E and F do and its notes
// expressly allow.
//
// Figures were generated by tools/state/generate_ca_method_b.py from EDD's
// "California Withholding Schedules for <year> - Method B" PDF (26methb.pdf,
// 27methb.pdf), not typed by hand. Bracket rows are [overCents, plusCents,
// rateMilli] where rateMilli is thousandths of a percent (1100 = 1.100%).
//
// Effective date: EDD publishes one schedule per calendar tax year with no
// mid-year change, so the tax year alone selects the table; 2027 applies to
// wages paid in 2027.
//
// Wages: California follows federal on 401(k) elective deferrals - they are
// "not subject to PIT withholding and not reportable as PIT wages" (EDD
// Information Sheet: Wages, DE 231A) - so the base is federal income-tax
// wages, not gross.
//
// DE 4 input: { filingStatus: "single" | "married" | "headOfHousehold",
//   regularAllowances, estimatedDeductionAllowances?, additionalWithholdingCents?,
//   exempt? }. "single" also covers "Married (with two or more incomes)".
// No DE 4 on file: Single with zero allowances (EDD DE 44, 2026; applied to
// 2027 too - the 27methb.pdf schedule does not address it).
//
// Interpretation to know: Tables 1 and 3 split married employees by
// "allowances on DE 4" ("0 or 1" vs "2 or more"). This uses REGULAR
// allowances (DE 4 line 1), the same count Method B uses for the credit.

/* eslint-disable prettier/prettier */
const TABLES = {
  2026: {
    lowIncomeExemptionCents: { single: 1889600, marriedZeroOrOne: 1889600, marriedTwoOrMore: 3779100, headOfHousehold: 3779100 },
    standardDeductionCents: { single: 570600, marriedZeroOrOne: 570600, marriedTwoOrMore: 1141200, headOfHousehold: 1141200 },
    estimatedDeductionPerAllowanceCents: 100000,
    exemptionCreditPerAllowanceCents: 16830,
    brackets: {
      single: [
        [0, 0, 1100],
        [1107900, 12187, 2200],
        [2626400, 45594, 4400],
        [4145200, 112421, 6600],
        [5754200, 218615, 8800],
        [7272400, 352217, 10230],
        [37147900, 3408481, 11330],
        [44577100, 4250209, 12430],
        [74295300, 7944181, 13530],
        [100000000, 11422027, 14630],
      ],
      married: [
        [0, 0, 1100],
        [2215800, 24374, 2200],
        [5252800, 91188, 4400],
        [8290400, 224842, 6600],
        [11508400, 437230, 8800],
        [14544800, 704433, 10230],
        [74295800, 6816960, 11330],
        [89154200, 8500417, 12430],
        [100000000, 9848550, 13530],
        [148590600, 16422858, 14630],
      ],
      headOfHousehold: [
        [0, 0, 1100],
        [2217300, 24390, 2200],
        [5253000, 91175, 4400],
        [6771600, 157993, 6600],
        [8380500, 264180, 8800],
        [9899000, 397808, 10230],
        [50520800, 4553418, 11330],
        [60625100, 5698235, 12430],
        [100000000, 10592535, 13530],
        [101041700, 10733477, 14630],
      ],
    },
    sources: [
      "EDD, California Withholding Schedules for 2026 - Method B: https://edd.ca.gov/siteassets/files/pdf_pub_ctr/26methb.pdf",
      "EDD, California Employer's Guide 2026 (DE 44): https://edd.ca.gov/siteassets/files/pdf_pub_ctr/de44.pdf",
      "EDD, Information Sheet: Wages (DE 231A): https://edd.ca.gov/siteassets/files/pdf_pub_ctr/de231a.pdf",
    ],
  },
  2027: {
    lowIncomeExemptionCents: { single: 1952800, marriedZeroOrOne: 1952800, marriedTwoOrMore: 3905600, headOfHousehold: 3905600 },
    standardDeductionCents: { single: 590000, marriedZeroOrOne: 590000, marriedTwoOrMore: 1180000, headOfHousehold: 1180000 },
    estimatedDeductionPerAllowanceCents: 100000,
    exemptionCreditPerAllowanceCents: 17380,
    brackets: {
      single: [
        [0, 0, 1100],
        [1145600, 12602, 2200],
        [2715700, 47144, 4400],
        [4286100, 116242, 6600],
        [5949800, 226046, 8800],
        [7519700, 364197, 10230],
        [38410900, 3524367, 11330],
        [46092700, 4394715, 12430],
        [76821300, 8214280, 13530],
        [100000000, 11350358, 14630],
      ],
      married: [
        [0, 0, 1100],
        [2291200, 25203, 2200],
        [5431400, 94287, 4400],
        [8572200, 232482, 6600],
        [11899600, 452090, 8800],
        [15039400, 728392, 10230],
        [76821800, 7048732, 11330],
        [92185400, 8789428, 12430],
        [100000000, 9760783, 13530],
        [153642600, 17018627, 14630],
      ],
      headOfHousehold: [
        [0, 0, 1100],
        [2292700, 25220, 2200],
        [5431600, 94276, 4400],
        [7001800, 163365, 6600],
        [8665400, 273163, 8800],
        [10235600, 411341, 10230],
        [52238500, 4708238, 11330],
        [62686400, 5891985, 12430],
        [100000000, 10530065, 13530],
        [103400000, 10990085, 14630],
      ],
    },
    sources: [
      "EDD, California Withholding Schedules for 2027 - Method B: https://edd.ca.gov/siteassets/files/pdf_pub_ctr/27methb.pdf",
      "EDD, California Employer's Guide (DE 44): https://edd.ca.gov/siteassets/files/pdf_pub_ctr/de44.pdf",
      "EDD, Information Sheet: Wages (DE 231A): https://edd.ca.gov/siteassets/files/pdf_pub_ctr/de231a.pdf",
    ],
  },
};
/* eslint-enable prettier/prettier */

const STATUSES = ["single", "married", "headOfHousehold"];

function validateForm(form) {
  if (form === null || form === undefined) return;
  const fail = (m) => {
    throw new Error(`California DE 4: ${m}`);
  };
  if (!STATUSES.includes(form.filingStatus)) fail(`filingStatus must be one of ${STATUSES.join(", ")}`);
  for (const k of ["regularAllowances", "estimatedDeductionAllowances"]) {
    const v = form[k] ?? 0;
    if (!Number.isInteger(v) || v < 0) fail(`${k} must be a non-negative integer`);
  }
  const extra = form.additionalWithholdingCents ?? 0;
  if (!Number.isSafeInteger(extra) || extra < 0) fail("additionalWithholdingCents must be a non-negative integer");
}

function columnFor(filingStatus, regularAllowances) {
  if (filingStatus === "married") return regularAllowances >= 2 ? "marriedTwoOrMore" : "marriedZeroOrOne";
  return filingStatus;
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const onFile = form !== null && form !== undefined;
  if (onFile && form.exempt) return { stateCents: 0, formBasis: "exempt", lines: {} };
  const f = onFile ? form : { filingStatus: "single", regularAllowances: 0 };
  const regular = f.regularAllowances ?? 0;
  const estimated = f.estimatedDeductionAllowances ?? 0;
  const extra = f.additionalWithholdingCents ?? 0;
  const column = columnFor(f.filingStatus, regular);

  const annualWages = wagesCents * payPeriodsPerYear;
  const lowIncomeLimit = t.lowIncomeExemptionCents[column];
  let annualTax = 0;
  let lines = { annualWages, lowIncomeLimit };

  if (annualWages > lowIncomeLimit) {
    const afterEstimated = annualWages - estimated * t.estimatedDeductionPerAllowanceCents; // Step 2
    const taxable = Math.max(0, afterEstimated - t.standardDeductionCents[column]); // Step 3
    let row = t.brackets[f.filingStatus][0];
    for (const r of t.brackets[f.filingStatus]) if (taxable > r[0]) row = r; // "over"
    const computed = row[1] + ((taxable - row[0]) * row[2]) / 100_000; // Step 4
    const credit = regular * t.exemptionCreditPerAllowanceCents; // Step 5
    annualTax = Math.max(0, computed - credit);
    lines = { ...lines, afterEstimated, taxable, computed, credit, annualTax };
  }

  return {
    stateCents: Math.round(annualTax / payPeriodsPerYear) + extra,
    formBasis: onFile ? "de4" : "none-on-file",
    lines,
  };
}

module.exports = {
  code: "CA",
  name: "California",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
